package com.soulknight.core;

public final class WorldSystem {

    private static final int MAGIC_STONES = 6;

    public static void initialize() {
        World world = World.load();
        Knight knight = new Knight();

        world.connectToMagicCore();
        knight.activateGuardianMode();

        System.out.println(
            "World synchronization started..."
        );
    }
}

